package com.rpb.reservation.workforce.documents;
import static com.rpb.reservation.workforce.documents.DocumentDtos.*;
import java.time.*;import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository
public class DocumentRepository {
 private final JdbcTemplate jdbc;public DocumentRepository(JdbcTemplate jdbc){this.jdbc=jdbc;}
 public void lockTypes(UUID tenant){jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"workforce.document-types:"+tenant);}
 public List<Type> types(UUID tenant){return jdbc.query("select id,name,enabled,version from workforce_document_types where tenant_id=? and deleted_at is null order by created_at,name,id",(r,n)->new Type(r.getObject(1,UUID.class),r.getString(2),r.getBoolean(3),r.getLong(4)),tenant);}
 public Optional<Type> type(UUID tenant,UUID id){return types(tenant).stream().filter(t->t.id().equals(id)).findFirst();}
 public boolean referenced(UUID tenant,UUID id){return jdbc.queryForObject("select exists(select 1 from workforce_employee_documents where tenant_id=? and type_id=?)",Boolean.class,tenant,id);}
 public void saveType(UUID tenant,UUID id,String name,boolean enabled,long version,boolean deleted){jdbc.update("insert into workforce_document_types(id,tenant_id,name,enabled,version,deleted_at) values(?,?,?,?,?,case when ? then now() end) on conflict(id) do update set name=excluded.name,enabled=excluded.enabled,version=excluded.version,deleted_at=excluded.deleted_at,updated_at=now() where workforce_document_types.tenant_id=excluded.tenant_id",id,tenant,name,enabled,version,deleted);}
 public List<Document> list(UUID tenant,UUID employee){return query(tenant,employee,null,false);}
 public Optional<Document> find(UUID tenant,UUID employee,UUID id,boolean deleted){return query(tenant,employee,id,deleted).stream().findFirst();}
 private List<Document> query(UUID tenant,UUID employee,UUID id,boolean deleted){return jdbc.query("select d.*,t.name type_name from workforce_employee_documents d join workforce_document_types t on t.id=d.type_id and t.tenant_id=d.tenant_id where d.tenant_id=? and d.employee_id=? and (?::uuid is null or d.id=?::uuid) and (? or d.deleted_at is null) order by d.created_at,d.id limit 101",(r,n)->new Document(r.getObject("id",UUID.class),r.getObject("type_id",UUID.class),r.getString("type_name"),r.getString("number"),r.getObject("expires_on",LocalDate.class),r.getString("notes"),r.getLong("version"),attachments(tenant,employee,r.getObject("id",UUID.class)),r.getString("holder_name"),r.getObject("approved_on",LocalDate.class),r.getObject("pr_effective_on",LocalDate.class)),tenant,employee,id,id,deleted);}
 public boolean deleted(UUID tenant,UUID employee,UUID id){return jdbc.queryForObject("select deleted_at is not null from workforce_employee_documents where tenant_id=? and employee_id=? and id=?",Boolean.class,tenant,employee,id);}
 public void save(UUID tenant,UUID employee,UUID id,UUID type,String number,LocalDate expiry,String notes,long version,UUID actor,boolean deleted,String holderName,LocalDate approvedOn,LocalDate prEffectiveOn){jdbc.update("insert into workforce_employee_documents(id,tenant_id,employee_id,type_id,number,expires_on,notes,version,created_by,updated_by,deleted_at,holder_name,approved_on,pr_effective_on) values(?,?,?,?,?,?,?,?,?,?,case when ? then now() end,?,?,?) on conflict(id) do update set type_id=excluded.type_id,number=excluded.number,expires_on=excluded.expires_on,notes=excluded.notes,holder_name=excluded.holder_name,approved_on=excluded.approved_on,pr_effective_on=excluded.pr_effective_on,version=excluded.version,updated_by=excluded.updated_by,deleted_at=excluded.deleted_at,updated_at=now() where workforce_employee_documents.tenant_id=excluded.tenant_id and workforce_employee_documents.employee_id=excluded.employee_id",id,tenant,employee,type,number,expiry,notes,version,actor,actor,deleted,holderName,approvedOn,prEffectiveOn);}
 public void bump(UUID tenant,UUID employee,UUID id,UUID actor){jdbc.update("update workforce_employee_documents set version=version+1,updated_by=?,updated_at=now() where tenant_id=? and employee_id=? and id=?",actor,tenant,employee,id);}
 public List<Attachment> attachments(UUID tenant,UUID employee,UUID doc){return jdbc.query("select id,filename,content_type,octet_length(content) from workforce_document_attachments where tenant_id=? and employee_id=? and document_id=? and deleted_at is null order by created_at,id",(r,n)->new Attachment(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getLong(4)),tenant,employee,doc);}
 public Optional<FileData> file(UUID tenant,UUID employee,UUID doc,UUID id){return jdbc.query("select id,filename,content_type,content,sha256,deleted_at is not null from workforce_document_attachments where tenant_id=? and employee_id=? and document_id=? and id=?",(r,n)->new FileData(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getBytes(4),r.getString(5),r.getBoolean(6)),tenant,employee,doc,id).stream().findFirst();}
 public void file(UUID tenant,UUID employee,UUID doc,UUID actor,FileData file){jdbc.update("insert into workforce_document_attachments(id,tenant_id,employee_id,document_id,filename,content_type,content,sha256,created_by) values(?,?,?,?,?,?,?,?,?)",file.id(),tenant,employee,doc,file.filename(),file.contentType(),file.bytes(),file.hash(),actor);}
 public void deleteFile(UUID tenant,UUID employee,UUID doc,UUID id){jdbc.update("update workforce_document_attachments set deleted_at=now() where tenant_id=? and employee_id=? and document_id=? and id=?",tenant,employee,doc,id);}
}
